<?php if ($product->price > 0 && $product->is_have !== '0' && $product->is_have !== '-'): ?>		<div class="prod-buttons">				<div class="quantity">			<div class="input-number__minus">-</div>			<input class="input-number__input" type="text" value="1" name="quantity">			<div class="input-number__plus"				 data-quantity-max="<?= $product->amount > 0 ? $product->amount : 999999 ?>">				+			</div>		</div>				<a href="cart/add?id=<?= $product->id ?>"		   class="add-to-cart-link to-cart hover"		   data-id="<?= $product->id ?>">			<img src="img/icons/cart-btn-light.svg" alt="в корзину">			<p>В корзину</p>		</a>				<a href="#modalProduct" class="one-click" data-toggle="modal-new"		   data-feedback="Заказать звонок: <?= $product->title ?>">			Купить в один клик		</a>		</div><?php endif; ?>